from typing import List

def parse_music(music_string: str) -> List[int]:
    note_durations = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }

    notes = music_string.split()
    result = []

    for note in notes:
        if note in note_durations:
            result.append(note_durations[note])

    return result

